def tokens(path, view_key):
    out = []
    other = 'L' if view_key == 'R' else 'R'          # 'W' = the key that brings the main-menu cursor back to SHOOT
    for t in path.split():
        out.append(view_key if t == 'V' else other if t == 'W' else t)
    return out
